const event=$input.first().json.body||{};
if(!event.order_id && !event.order?.id) return [];
if(event.type && !['order.created','order.validated','order.confirmed','order.cancelled','order.shipped','shipment.updated','payment.reconciled','inventory.reserved','warehouse.ready','warehouse.updated','order.review_required'].includes(event.type))return [];
return [{json:{event,orderId:String(event.order_id||event.order.id),shopBaseUrl:'https://erik-unbarking-foolhardily.ngrok-free.dev',logisticsWebhookUrl:'https://cosmos-team-5ia.app.n8n.cloud/webhook/order-ready-for-shipment'}}];

const input = $input.first().json;
const order = input.order || input;
const products = order.products || order.items || [];
return [{ json: { body: { order_id: order.order_id || order.id, items: products.map((p) => ({ sku: p.sku || p.productId, name: p.name, qty: Number(p.qty ?? p.quantity), price: p.price ?? p.unitPrice })) }, order } }];

const lines = $('INV | Split Out Items').all().map((item) => item.json);
const rows = $input.all().map((item) => item.json);
const checked = lines.map((line) => {
  const product = rows.find((row) => row.sku === line.sku) || {};
  const qty = Number(line.qty);
  const available = Number(product.available ?? 0);
  const reserved = Number(product.reserved ?? 0);
  return { sku: line.sku, name: line.name, qty, reserved, available, ok: !!product.sku && available >= qty };
});
const stockErrors = checked.filter((item) => !item.ok).map((item) => 'Insufficient or unknown stock: ' + item.sku);
const all_ok = checked.length > 0 && checked.every((item) => item.ok);
return checked.map((item) => ({ json: { ...item, order_id: $('INV | Prepare Order').first().json.body.order_id, stockErrors, all_ok } }));

const prepared = $('INV | Prepare Order').first().json;
const checked = $('INV | Check Stock').all().map((item) => item.json);
return [{ json: { order_id: prepared.body.order_id, items: prepared.body.items, reserved_items: checked.map((item) => ({ sku: item.sku, name: item.name, qty: item.qty, available_before: item.available, available_after: item.available - item.qty })) } }];

const task = $input.first().json;
const prepared = $('INV | Prepare Order').first().json;
const order = prepared.order || {};
return [{ json: { warehouse_task_id: task.task_id || 'TASK-' + prepared.body.order_id, order_id: prepared.body.order_id, products: prepared.body.items, quantities: Object.fromEntries(prepared.body.items.map((item) => [item.sku, item.qty])), shipping_address: order.shipping_address, status: 'pending', human_steps: ['pick products', 'verify products', 'package order'], assigned_to: 'Warehouse team', created_at: new Date().toISOString() } }];
